// Configure Authentication Header
msg.headers = {
    "Content-Type": "application/json",
    "x-api-key": env.get("IOT_API_KEY") || "lnmiit_nodered_secure_key_2026"
};

// If triggered by explicit test button
if (msg.payload && (msg.payload.temperature || msg.payload.ultrasonicDistance)) {
    msg.payload = {
        bedNumber: 1,
        deviceId: "RPI_BED_1_HARDWARE",
        temperature: parseFloat(msg.payload.temperature || 36.8),
        ultrasonicDistance: parseFloat(msg.payload.ultrasonicDistance || 32.5),
        force: parseFloat(msg.payload.force || 45.0),
        timestamp: Date.now()
    };
    return msg;
}

// Realistic live readings with natural sensor jitter
// Connect your Raspberry Pi ADC/I2C/GPIO inputs here:
var jitter = (Math.random() - 0.5);
var temp = parseFloat((36.8 + jitter * 0.15).toFixed(1));
var dist = parseFloat((32.5 + Math.sin(Date.now() / 4000) * 1.5 + jitter).toFixed(1));
var force = parseFloat((46.0 + Math.sin(Date.now() / 5000) * 2.0 + jitter).toFixed(1));

msg.payload = {
    bedNumber: 1,
    deviceId: "RPI_BED_1_HARDWARE",
    temperature: temp,
    ultrasonicDistance: dist,
    force: force,
    timestamp: Date.now()
};

return msg;

